import re
from datetime import datetime

_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_DIGITS = "0123456789"


def _is_digits(s):
    return s != "" and all(c in _DIGITS for c in s)


def _normalize_email(raw):
    s = (raw or "").strip()
    if "<" in s:
        start = s.find("<")
        end = s.find(">", start)
        if end != -1:
            s = s[start + 1:end]
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "").split("+", 1)[0]
            s = f"{local}@gmail.com"
    return s


def _email_is_valid(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (
        local != ""
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _normalize_phone(raw):
    s = raw or ""
    lower = s.lower()
    cuts = [i for i in (lower.find("x"), lower.find("ext"), lower.find("#")) if i != -1]
    if cuts:
        s = s[:min(cuts)]
    digits = "".join(c for c in s if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _phone_is_valid(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _normalize_zip(raw):
    s = (raw or "").strip()
    head, sep, tail = s.partition("-")
    if sep and _is_digits(head) and len(tail) == 4 and _is_digits(tail):
        s = head
    if _is_digits(s) and len(s) == 4:
        s = "0" + s
    if _is_digits(s) and len(s) == 5:
        return s
    return ""


def _normalize_name(raw):
    s = (raw or "").strip()
    if s and (s.isupper() or s.islower()):
        s = s.title()
    return s


def _parse_updated(raw):
    s = (raw or "").strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _is_opted_out(raw):
    return (raw or "").strip().lower() in {"y", "yes", "true", "1"}


def _parse_tags(raw):
    return {t.strip().lower() for t in re.split(r"[;,]", raw or "") if t.strip()}


def dedupe_contacts(rows):
    # Normalize each row; drop rows with neither a valid email nor a valid phone.
    # Invalid email/phone values are blanked to "", so "non-empty" == "valid".
    recs = []
    for idx, row in enumerate(rows):
        email = _normalize_email(row.get("email", ""))
        if not _email_is_valid(email):
            email = ""
        phone = _normalize_phone(row.get("phone", ""))
        if not _phone_is_valid(phone):
            phone = ""
        if not email and not phone:
            continue
        recs.append({
            "idx": idx,
            "first_name": _normalize_name(row.get("first_name", "")),
            "last_name": _normalize_name(row.get("last_name", "")),
            "zip": _normalize_zip(row.get("zip", "")),
            "email": email,
            "phone": phone,
            "source": (row.get("source") or "").strip().lower(),
            "tags": _parse_tags(row.get("tags", "")),
            "opted_out": _is_opted_out(row.get("opted_out", "")),
            "updated": _parse_updated(row.get("updated", "")),
        })

    # Union-find over matching rows (transitive matching).
    parent = list(range(len(recs)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)

    email_seen = {}
    phone_seen = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in email_seen:
                union(email_seen[r["email"]], i)
            else:
                email_seen[r["email"]] = i
        if r["phone"] and r["last_name"]:
            key = (r["phone"], r["last_name"].lower())
            if key in phone_seen:
                union(phone_seen[key], i)
            else:
                phone_seen[key] = i

    groups = {}
    for i in range(len(recs)):
        groups.setdefault(find(i), []).append(i)
    # Member lists are already in input order, so g[0] is each group's earliest row.
    ordered_groups = sorted(groups.values(), key=lambda g: g[0])

    def pick(members, field):
        cands = [i for i in members if recs[i][field]]
        if not cands:
            return ""
        # Stable sorts: first order by most recent, then move "manual" rows
        # to the front; ties keep input order.
        cands.sort(key=lambda i: recs[i]["updated"], reverse=True)
        cands.sort(key=lambda i: recs[i]["source"] != "manual")
        return recs[cands[0]][field]

    output = []
    for members in ordered_groups:
        all_tags = set()
        for i in members:
            all_tags |= recs[i]["tags"]
        output.append({
            "first_name": pick(members, "first_name"),
            "last_name": pick(members, "last_name"),
            "zip": pick(members, "zip"),
            "email": pick(members, "email"),
            "phone": pick(members, "phone"),
            "source": pick(members, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": "Y" if any(recs[i]["opted_out"] for i in members) else "N",
            "updated": max(recs[i]["updated"] for i in members).strftime("%Y-%m-%d"),
        })
    return output
